"""Module handling the cleaning up of malformed CSVs using heuristics."""

from __future__ import annotations

from typing import Any, Callable, Optional, Tuple

import numpy as np
import pandas as pd

from csv_trimming.logger import logger

try:
    from ugly_csv_generator.utils.add_nan_like_artefacts import (
        NAN_LIKE_ARTIFACTS,
        UNICODE_NAN_LIKE_ARTIFACTS,
    )
    from ugly_csv_generator.utils.add_random_spaces import SPACES, UNICODE_SPACES
except Exception:
    NAN_LIKE_ARTIFACTS = [
        "",
        "\n",
        "\r",
        "\n\r",
        "?",
        "NaN",
        "Nan",
        "_",
        "/",
        " ",
        "-",
        "NA",
        ".",
        np.nan,
        None,
        "null",
        "#RIF!",
        "#N/D",
        "N/A",
        "O",
        "o",
        "0",
    ]
    UNICODE_NAN_LIKE_ARTIFACTS = ["�", "∞", "⧜", "¿", "无", "０", "⓪", "⓿", "О", "о"]
    SPACES = [" ", "\t", "\n", "\n\r"]
    UNICODE_SPACES = [
        "\xa0",
        "\u1680",
        "\u2000",
        "\u2001",
        "\u2002",
        "\u2003",
        "\u2004",
        "\u2005",
        "\u2006",
        "\u2007",
        "\u2008",
        "\u2009",
        "\u200a",
        "\u200b",
        "\u200c",
        "\u200d",
        "\u202f",
        "\u205f",
        "\u3000",
        "\ufeff",
    ]


NAN_LIKE = NAN_LIKE_ARTIFACTS + UNICODE_NAN_LIKE_ARTIFACTS
SPACE_LIKE = sorted(SPACES + UNICODE_SPACES, key=lambda value: -len(value))
_NAN_LIKE_STRINGS = {
    value.casefold()
    for value in NAN_LIKE
    if isinstance(value, str)
}


def _dataframe_map(csv: pd.DataFrame, func: Callable[[Any], Any]) -> pd.DataFrame:
    """Compatibly map a scalar function over a DataFrame."""
    if hasattr(csv, "map"):
        return csv.map(func)
    return csv.applymap(func)


def is_nan(candidate: Any) -> bool:
    """Return True if the given candidate is NaN-like."""
    if candidate is None:
        return True

    try:
        if pd.isna(candidate):
            return True
    except Exception:
        pass

    try:
        if candidate in NAN_LIKE:
            return True
    except Exception:
        pass

    if isinstance(candidate, str):
        if len(candidate) > 1 and all(is_nan(char) for char in candidate):
            return True

        normalized = candidate
        for char in SPACE_LIKE:
            if char in normalized:
                normalized = normalized.replace(char, " ")
        normalized = " ".join(part for part in normalized.split(" ") if part).strip()

        if not normalized:
            return True

        if normalized.casefold() in _NAN_LIKE_STRINGS:
            return True

    return False


class CSVTrimmer:
    """Class handling the cleaning up of malformed CSVs using heuristics."""

    def __init__(
        self,
        correlation_callback: Optional[
            Callable[[pd.Series, pd.Series], Tuple[bool, pd.Series]]
        ] = None,
    ):
        """Create a new CSVTrimmer object."""
        self._correlation_callback = correlation_callback

    def _mask_edges(self, mask: np.ndarray) -> np.ndarray:
        """Return boolean array with only the True values attached to the sides."""
        mask = np.asarray(mask, dtype=bool).copy()
        if mask.size == 0:
            return mask

        for left, value in enumerate(mask):
            if not value:
                break
        else:
            left = len(mask)

        for right, value in enumerate(mask[::-1]):
            if not value:
                break
        else:
            right = len(mask)

        if right == 0:
            mask[left:] = False
        else:
            mask[left:-right] = False

        return mask

    def trim_padding(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return given CSV with trimmed rows and columns."""
        if csv.empty:
            return csv.copy()

        nan_mask = _dataframe_map(csv, is_nan)
        rows_threshold = np.logical_not(nan_mask).sum(axis=1).mean() / 2
        rows_mask = self._mask_edges((~nan_mask).sum(axis=1).to_numpy() < rows_threshold)
        columns_mask = self._mask_edges(nan_mask.all(axis=0).to_numpy())

        return csv.loc[~rows_mask, csv.columns[~columns_mask]].copy()

    def restore_header(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return CSV with restored first row as header of CSV."""
        if csv.empty:
            return csv.copy()

        new_header = csv.iloc[0]
        new_sanitized_header = []
        nan_values_count = 0

        for value in new_header:
            if isinstance(value, str):
                value = self._deep_strip(value)

            if is_nan(value):
                value = f"column #{nan_values_count}"
                nan_values_count += 1

            base_value = value
            duplicate_counter = 0
            while value in new_sanitized_header:
                duplicate_counter += 1
                suffix = ".duplicated" if duplicate_counter == 1 else f".duplicated{duplicate_counter}"
                value = f"{base_value}{suffix}"

            new_sanitized_header.append(value)

        restored = csv.iloc[1:].copy()
        restored.columns = new_sanitized_header
        return restored

    def drop_empty_columns(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return DataFrame with removed empty columns."""
        if csv.empty:
            return csv.copy()
        nan_mask = _dataframe_map(csv, is_nan).all(axis=0)
        return csv.loc[:, ~nan_mask].copy()

    def drop_duplicated_schema(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return DataFrame with removed duplicated schema."""
        if csv.empty:
            return csv.copy()

        header = [
            self._deep_strip(column) if isinstance(column, str) else column
            for column in csv.columns
        ]
        indices_to_drop = []

        for idx, row in csv.iterrows():
            normalized_row = [
                self._deep_strip(value) if isinstance(value, str) else value
                for value in row.tolist()
            ]
            if len(normalized_row) == len(header) and all(
                left == right for left, right in zip(normalized_row, header)
            ):
                indices_to_drop.append(idx)

        return csv.drop(index=indices_to_drop)

    def drop_empty_rows(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return DataFrame with removed empty rows."""
        if csv.empty:
            return csv.copy()
        nan_mask = _dataframe_map(csv, is_nan).all(axis=1)
        return csv.loc[~nan_mask].copy()

    def _deep_strip(self, string: str):
        """Return string without continuous spaces."""
        if not isinstance(string, str):
            return string

        old_string = None
        while old_string != string:
            old_string = string
            for char in SPACE_LIKE:
                if char in string:
                    string = " ".join(token for token in string.split(char) if token)
        return string.strip()

    def trim_spaces(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return dataframe without multiple spaces."""
        return _dataframe_map(
            csv,
            lambda value: self._deep_strip(value) if isinstance(value, str) else value,
        )

    def restore_true_nan(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return CSV with restored true NaN values."""
        nan_mask = _dataframe_map(csv, is_nan)
        return csv.where(np.logical_not(nan_mask))

    def normalize_correlated_rows(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return normalized correlated rows."""
        if self._correlation_callback is None or csv.empty:
            return csv.copy()

        new_rows = []
        row_index = 0

        while row_index < len(csv):
            current_row = csv.iloc[row_index]

            if row_index + 1 >= len(csv):
                new_rows.append(current_row)
                break

            next_row = csv.iloc[row_index + 1]
            skip_next, result = self._correlation_callback(current_row, next_row)
            new_rows.append(result)
            row_index += 2 if skip_next else 1

        return pd.DataFrame(new_rows)

    def trim(
        self,
        csv: pd.DataFrame,
        restore_header: bool = True,
        drop_padding: bool = True,
        drop_duplicated_schema: bool = True,
    ) -> pd.DataFrame:
        """Return sanitized version of given dataframe."""
        logger.info("Removing extra spaces within cells.")
        csv = self.trim_spaces(csv)

        if drop_padding:
            logger.info("Removing empty space (or NaNs).")
            csv = self.trim_padding(csv)

        logger.info("Removing empty space rows.")
        csv = self.drop_empty_rows(csv)

        if restore_header:
            logger.info("Restoring detected header.")
            csv = self.restore_header(csv)

        logger.info("Restoring true NaN values.")
        csv = self.restore_true_nan(csv)

        logger.info("Normalizing correlated rows (if lambda is provided).")
        csv = self.normalize_correlated_rows(csv)

        logger.info("Dropping empty columns.")
        csv = self.drop_empty_columns(csv)

        if drop_duplicated_schema:
            logger.info("Dropping rows containing duplicated schema.")
            csv = self.drop_duplicated_schema(csv)

        csv = csv.reset_index(drop=True)
        csv.index.name = None
        csv.columns.name = None
        return csv


def trim(
    csv: pd.DataFrame,
    restore_header: bool = True,
    drop_padding: bool = True,
    drop_duplicated_schema: bool = True,
    correlation_callback: Optional[
        Callable[[pd.Series, pd.Series], Tuple[bool, pd.Series]]
    ] = None,
) -> pd.DataFrame:
    """Convenience wrapper around :class:`CSVTrimmer`."""
    return CSVTrimmer(correlation_callback=correlation_callback).trim(
        csv,
        restore_header=restore_header,
        drop_padding=drop_padding,
        drop_duplicated_schema=drop_duplicated_schema,
    )

